  (200011, 1, 'Varfariin + K-vitamiinirikkad rohelised köögiviljad'),
  (200011, 2, 'Varfariin + K-vitamiinirikkad rohelised köögiviljad'),
  (200012, 1, 'K-vitamiin on varfariini farmakoloogilise sihtmehhanismi vastasmõjur: suurenenud või järsult kõikuv K-vitamiini tarbimine võib vähendada INR-i ja varfariini antikoagulantset toimet; järsk K-vitamiini vähendamine võib suurendada veritsusriski.'),
  (200012, 2, 'K-vitamiin on varfariini farmakoloogilise sihtmehhanismi vastasmõjur: suurenenud või järsult kõikuv K-vitamiini tarbimine võib vähendada INR-i ja varfariini antikoagulantset toimet; järsk K-vitamiini vähendamine võib suurendada veritsusriski.'),
  (200013, 1, 'Kontrolli enne koos kasutamist: Varfariin + K-vitamiinirikkad rohelised köögiviljad'),
  (200013, 2, 'Kontrolli enne koos kasutamist: Varfariin + K-vitamiinirikkad rohelised köögiviljad'),
  (200014, 1, 'K-vitamiin on varfariini farmakoloogilise sihtmehhanismi vastasmõjur: suurenenud või järsult kõikuv K-vitamiini tarbimine võib vähendada INR-i ja varfariini antikoagulantset toimet; järsk K-vitamiini vähendamine võib ...'),
  (200014, 2, 'K-vitamiin on varfariini farmakoloogilise sihtmehhanismi vastasmõjur: suurenenud või järsult kõikuv K-vitamiini tarbimine võib vähendada INR-i ja varfariini antikoagulantset toimet; järsk K-vitamiini vähendamine võib ...'),
  (200015, 1, 'Praktiline samm: Ära keela rohelisi köögivilju, kuid hoia K-vitamiini tarbimine võimalikult stabiilne. Uut K-vitamiini toidulisandit ei tohiks alustada ilma arsti/apteekriga nõu pidamata; INR-i muutuste korral tuleb annust jälgida. Kui ravim on arsti määratud, ära muuda raviskeemi omal käel; kontrolli kombinatsioon arstilt või apteekrilt.'),
  (200015, 2, 'Praktiline samm: Ära keela rohelisi köögivilju, kuid hoia K-vitamiini tarbimine võimalikult stabiilne. Uut K-vitamiini toidulisandit ei tohiks alustada ilma arsti/apteekriga nõu pidamata; INR-i muutuste korral tuleb annust jälgida. Kui ravim on arsti määratud, ära muuda raviskeemi omal käel; kontrolli kombinatsioon arstilt või apteekrilt.'),
  (200016, 1, 'Ära keela rohelisi köögivilju, kuid hoia K-vitamiini tarbimine võimalikult stabiilne. Uut K-vitamiini toidulisandit ei tohiks alustada ilma arsti/apteekriga nõu pidamata; INR-i muutuste korral tuleb annust jälgida.'),
  (200016, 2, 'Ära keela rohelisi köögivilju, kuid hoia K-vitamiini tarbimine võimalikult stabiilne. Uut K-vitamiini toidulisandit ei tohiks alustada ilma arsti/apteekriga nõu pidamata; INR-i muutuste korral tuleb annust jälgida.'),
  (200021, 1, 'Simvastatiin + greip / greibimahl'),
  (200021, 2, 'Simvastatiin + greip / greibimahl'),
  (200022, 1, 'Greibimahl inhibeerib sooleseina CYP3A4 ensüümi ja võib märgatavalt suurendada simvastatiini süsteemset ekspositsiooni. See tõstab müopaatia ja rabdomüolüüsi riski.'),
  (200022, 2, 'Greibimahl inhibeerib sooleseina CYP3A4 ensüümi ja võib märgatavalt suurendada simvastatiini süsteemset ekspositsiooni. See tõstab müopaatia ja rabdomüolüüsi riski.'),
  (200023, 1, 'Kontrolli enne koos kasutamist: Simvastatiin + greip / greibimahl'),
  (200023, 2, 'Kontrolli enne koos kasutamist: Simvastatiin + greip / greibimahl'),
  (200024, 1, 'Greibimahl inhibeerib sooleseina CYP3A4 ensüümi ja võib märgatavalt suurendada simvastatiini süsteemset ekspositsiooni.'),
  (200024, 2, 'Greibimahl inhibeerib sooleseina CYP3A4 ensüümi ja võib märgatavalt suurendada simvastatiini süsteemset ekspositsiooni.'),
  (200025, 1, 'Praktiline samm: Simvastatiini kasutamisel väldi greipi ja greibimahla. Kui patsient tarvitab greipi regulaarselt, tuleks kaaluda arsti/apteekriga alternatiivset statiini või raviskeemi. Kui ravim on arsti määratud, ära muuda raviskeemi omal käel; kontrolli kombinatsioon arstilt või apteekrilt.'),
  (200025, 2, 'Praktiline samm: Simvastatiini kasutamisel väldi greipi ja greibimahla. Kui patsient tarvitab greipi regulaarselt, tuleks kaaluda arsti/apteekriga alternatiivset statiini või raviskeemi. Kui ravim on arsti määratud, ära muuda raviskeemi omal käel; kontrolli kombinatsioon arstilt või apteekrilt.'),
  (200026, 1, 'Simvastatiini kasutamisel väldi greipi ja greibimahla. Kui patsient tarvitab greipi regulaarselt, tuleks kaaluda arsti/apteekriga alternatiivset statiini või raviskeemi.'),
  (200026, 2, 'Simvastatiini kasutamisel väldi greipi ja greibimahla. Kui patsient tarvitab greipi regulaarselt, tuleks kaaluda arsti/apteekriga alternatiivset statiini või raviskeemi.'),
  (200031, 1, 'Atorvastatiin + greip / greibimahl'),
  (200031, 2, 'Atorvastatiin + greip / greibimahl'),
  (200032, 1, 'Greibimahl inhibeerib sooleseina CYP3A4 aktiivsust ja võib suurendada atorvastatiini kontsentratsiooni, kuigi toime on üldiselt väiksem kui simvastatiinil/lovastatiinil. Suure koguse greibi korral suureneb lihaskahjustuse risk.'),
  (200032, 2, 'Greibimahl inhibeerib sooleseina CYP3A4 aktiivsust ja võib suurendada atorvastatiini kontsentratsiooni, kuigi toime on üldiselt väiksem kui simvastatiinil/lovastatiinil. Suure koguse greibi korral suureneb lihaskahjustuse risk.'),
  (200033, 1, 'Kontrolli enne koos kasutamist: Atorvastatiin + greip / greibimahl'),
  (200033, 2, 'Kontrolli enne koos kasutamist: Atorvastatiin + greip / greibimahl'),
  (200034, 1, 'Greibimahl inhibeerib sooleseina CYP3A4 aktiivsust ja võib suurendada atorvastatiini kontsentratsiooni, kuigi toime on üldiselt väiksem kui simvastatiinil/lovastatiinil.'),
  (200034, 2, 'Greibimahl inhibeerib sooleseina CYP3A4 aktiivsust ja võib suurendada atorvastatiini kontsentratsiooni, kuigi toime on üldiselt väiksem kui simvastatiinil/lovastatiinil.'),
  (200035, 1, 'Praktiline samm: Väldi suurtes kogustes greibimahla. Juhuslik väike kogus ei pruugi kõigil olla kliiniliselt oluline, kuid regulaarne tarbimine tuleks arstiga läbi rääkida. Kui ravim on arsti määratud, ära muuda raviskeemi omal käel; kontrolli kombinatsioon arstilt või apteekrilt.'),
  (200035, 2, 'Praktiline samm: Väldi suurtes kogustes greibimahla. Juhuslik väike kogus ei pruugi kõigil olla kliiniliselt oluline, kuid regulaarne tarbimine tuleks arstiga läbi rääkida. Kui ravim on arsti määratud, ära muuda raviskeemi omal käel; kontrolli kombinatsioon arstilt või apteekrilt.'),
  (200036, 1, 'Väldi suurtes kogustes greibimahla. Juhuslik väike kogus ei pruugi kõigil olla kliiniliselt oluline, kuid regulaarne tarbimine tuleks arstiga läbi rääkida.'),
  (200036, 2, 'Väldi suurtes kogustes greibimahla. Juhuslik väike kogus ei pruugi kõigil olla kliiniliselt oluline, kuid regulaarne tarbimine tuleks arstiga läbi rääkida.'),
  (200041, 1, 'Levotüroksiin + kaltsiumilisandid'),
  (200041, 2, 'Levotüroksiin + kaltsiumilisandid'),
  (200042, 1, 'Kaltsium võib siduda levotüroksiini seedetraktis ja vähendada selle imendumist; uuringutes on nähtud T4 imendumise olulist langust, kui kaltsium võetakse samal ajal.'),
  (200042, 2, 'Kaltsium võib siduda levotüroksiini seedetraktis ja vähendada selle imendumist; uuringutes on nähtud T4 imendumise olulist langust, kui kaltsium võetakse samal ajal.'),
