  (200044, 2, 'Kaltsium võib siduda levotüroksiini seedetraktis ja vähendada selle imendumist; uuringutes on nähtud T4 imendumise olulist langust, kui kaltsium võetakse samal ajal.'),
  (200045, 1, 'Praktiline samm: Võta levotüroksiin tühja kõhuga veega. Kaltsiumilisand jäta üldjuhul vähemalt 4 tunni kaugusele, eriti kui TSH kõigub või annust on raske paika saada. Kui ravim on arsti määratud, ära muuda raviskeemi omal käel; kontrolli kombinatsioon arstilt või apteekrilt.'),
  (200045, 2, 'Praktiline samm: Võta levotüroksiin tühja kõhuga veega. Kaltsiumilisand jäta üldjuhul vähemalt 4 tunni kaugusele, eriti kui TSH kõigub või annust on raske paika saada. Kui ravim on arsti määratud, ära muuda raviskeemi omal käel; kontrolli kombinatsioon arstilt või apteekrilt.'),
  (200046, 1, 'Võta levotüroksiin tühja kõhuga veega. Kaltsiumilisand jäta üldjuhul vähemalt 4 tunni kaugusele, eriti kui TSH kõigub või annust on raske paika saada.'),
  (200046, 2, 'Võta levotüroksiin tühja kõhuga veega. Kaltsiumilisand jäta üldjuhul vähemalt 4 tunni kaugusele, eriti kui TSH kõigub või annust on raske paika saada.'),
  (200051, 1, 'Levotüroksiin + kohv'),
  (200051, 2, 'Levotüroksiin + kohv'),
  (200052, 1, 'Kohv võib vähendada tablett-levotüroksiini seedetrakti imendumist, tõenäoliselt lahustumise, adsorptsiooni ja/või seedetrakti motoorika muutuste kaudu. Probleem on eelkõige siis, kui kohv võetakse kohe ravimiga või mõne minuti jooksul.'),
  (200052, 2, 'Kohv võib vähendada tablett-levotüroksiini seedetrakti imendumist, tõenäoliselt lahustumise, adsorptsiooni ja/või seedetrakti motoorika muutuste kaudu. Probleem on eelkõige siis, kui kohv võetakse kohe ravimiga või mõne minuti jooksul.'),
  (200053, 1, 'Ajasta või piira: Levotüroksiin + kohv'),
  (200053, 2, 'Ajasta või piira: Levotüroksiin + kohv'),
  (200054, 1, 'Kohv võib vähendada tablett-levotüroksiini seedetrakti imendumist, tõenäoliselt lahustumise, adsorptsiooni ja/või seedetrakti motoorika muutuste kaudu.'),
  (200054, 2, 'Kohv võib vähendada tablett-levotüroksiini seedetrakti imendumist, tõenäoliselt lahustumise, adsorptsiooni ja/või seedetrakti motoorika muutuste kaudu.'),
  (200055, 1, 'Praktiline samm: Võta tablett-levotüroksiin veega ja oota enne kohvi tavaliselt 30–60 minutit. Kui see pole võimalik ja TSH kõigub, aruta arstiga vedela või pehmekapsli vormi võimalust. Hoia ajastus/kogus järjepidev ning küsi nõu, kui kasutad seda regulaarselt või sul on riskitegureid.'),
  (200055, 2, 'Praktiline samm: Võta tablett-levotüroksiin veega ja oota enne kohvi tavaliselt 30–60 minutit. Kui see pole võimalik ja TSH kõigub, aruta arstiga vedela või pehmekapsli vormi võimalust. Hoia ajastus/kogus järjepidev ning küsi nõu, kui kasutad seda regulaarselt või sul on riskitegureid.'),
  (200056, 1, 'Võta tablett-levotüroksiin veega ja oota enne kohvi tavaliselt 30–60 minutit. Kui see pole võimalik ja TSH kõigub, aruta arstiga vedela või pehmekapsli vormi võimalust.'),
  (200056, 2, 'Võta tablett-levotüroksiin veega ja oota enne kohvi tavaliselt 30–60 minutit. Kui see pole võimalik ja TSH kõigub, aruta arstiga vedela või pehmekapsli vormi võimalust.'),
