  (200062, 2, 'Raud võib moodustada levotüroksiiniga seedetraktis komplekse ning vähendada ravimi imendumist. Kliiniliselt võib see väljenduda TSH tõusus ja hüpotüreoosi sümptomite taastumises.'),
