  (200075, 2, 'Praktiline samm: Väldi ravimi võtmist koos piima, jogurti või kaltsiumilisandiga. Kasuta ajavahet: ravim vähemalt 2 tundi enne või 4–6 tundi pärast mineraal-/kaltsiumilisandit; täpne juhis sõltub preparaadist. Kui ravim on arsti määratud, ära muuda raviskeemi omal käel; kontrolli kombinatsioon arstilt või apteekrilt.'),
