  (200085, 2, 'Praktiline samm: Võta antibiootikum veega ning hoia piimatoodete ja mineraalilisanditega ajavahe. Kui infektsioon on tõsine, järgi pakendi/infolehe täpset ajastamisjuhist ja küsi apteekrilt. Kui ravim on arsti määratud, ära muuda raviskeemi omal käel; kontrolli kombinatsioon arstilt või apteekrilt.'),
