  (200092, 1, 'Alendronaadi suukaudne biosaadavus on väga väike ning toit ja mineraalid vähendavad seda veelgi. Ka liiga lühike vahe ravimi ja hommikusöögi vahel võib ravimi imendumist oluliselt vähendada.'),
  (200092, 2, 'Alendronaadi suukaudne biosaadavus on väga väike ning toit ja mineraalid vähendavad seda veelgi. Ka liiga lühike vahe ravimi ja hommikusöögi vahel võib ravimi imendumist oluliselt vähendada.'),
