  (200095, 1, 'Praktiline samm: Võta alendronaat hommikul tühja kõhuga ainult tavalise veega. Ära söö, joo muid jooke ega võta toidulisandeid vähemalt 30 minutit; paljudes juhistes eelistatakse pikemat vahet, kui see on võimalik. Kui ravim on arsti määratud, ära muuda raviskeemi omal käel; kontrolli kombinatsioon arstilt või apteekrilt.'),
  (200095, 2, 'Praktiline samm: Võta alendronaat hommikul tühja kõhuga ainult tavalise veega. Ära söö, joo muid jooke ega võta toidulisandeid vähemalt 30 minutit; paljudes juhistes eelistatakse pikemat vahet, kui see on võimalik. Kui ravim on arsti määratud, ära muuda raviskeemi omal käel; kontrolli kombinatsioon arstilt või apteekrilt.'),
  (200096, 1, 'Võta alendronaat hommikul tühja kõhuga ainult tavalise veega. Ära söö, joo muid jooke ega võta toidulisandeid vähemalt 30 minutit; paljudes juhistes eelistatakse pikemat vahet, kui see on võimalik.'),
  (200096, 2, 'Võta alendronaat hommikul tühja kõhuga ainult tavalise veega. Ära söö, joo muid jooke ega võta toidulisandeid vähemalt 30 minutit; paljudes juhistes eelistatakse pikemat vahet, kui see on võimalik.'),
  (200101, 1, 'AKE inhibiitorid / ARB-id + kaaliumilisandid või kaaliumisool'),
  (200101, 2, 'AKE inhibiitorid / ARB-id + kaaliumilisandid või kaaliumisool'),
  (200102, 1, 'AKE inhibiitorid ja ARB-id vähendavad aldosterooni toimet ning võivad tõsta seerumi kaaliumi. Kaaliumilisandid või kaaliumkloriidi sisaldavad soolaasendajad võivad lisada koormust ja põhjustada hüperkaleemiat, eriti neeruhaiguse, diabeedi, eakuse või spironolaktooni kasutamise korral.'),
  (200102, 2, 'AKE inhibiitorid ja ARB-id vähendavad aldosterooni toimet ning võivad tõsta seerumi kaaliumi. Kaaliumilisandid või kaaliumkloriidi sisaldavad soolaasendajad võivad lisada koormust ja põhjustada hüperkaleemiat, eriti neeruhaiguse, diabeedi, eakuse või spironolaktooni kasutamise korral.'),
  (200103, 1, 'Kontrolli enne koos kasutamist: AKE inhibiitorid / ARB-id + kaaliumilisandid või kaaliumisool'),
