  (200104, 2, 'AKE inhibiitorid ja ARB-id vähendavad aldosterooni toimet ning võivad tõsta seerumi kaaliumi.'),
  (200105, 1, 'Praktiline samm: Ära alusta kaaliumilisandit ega kaaliumisoola ilma arstiga nõu pidamata. Riskirühmadel on vaja kaaliumi ja neerufunktsiooni kontrolli; südamepekslemise, nõrkuse või minestustunde korral tuleb kiiresti abi otsida. Kui ravim on arsti määratud, ära muuda raviskeemi omal käel; kontrolli kombinatsioon arstilt või apteekrilt.'),
  (200105, 2, 'Praktiline samm: Ära alusta kaaliumilisandit ega kaaliumisoola ilma arstiga nõu pidamata. Riskirühmadel on vaja kaaliumi ja neerufunktsiooni kontrolli; südamepekslemise, nõrkuse või minestustunde korral tuleb kiiresti abi otsida. Kui ravim on arsti määratud, ära muuda raviskeemi omal käel; kontrolli kombinatsioon arstilt või apteekrilt.'),
